// @vitest-environment jsdom
// Local independent UI probe; no worker test/helper import and no provider call.
// Text Encoding Exception: actual Vietnamese UI labels and field choices.
import { act, fireEvent, render, screen, waitFor } from '@testing-library/react';
import { afterEach, beforeEach, expect, it, vi } from 'vitest';
import Home from './page';
import { useExecutionStore } from '@/lib/store';
import type { Execution } from '@/types';
const nav = vi.hoisted(() => ({ p: new URLSearchParams() }));
vi.mock('next/navigation', () => ({ useSearchParams: () => nav.p, useRouter: () => ({ push: vi.fn(), replace: vi.fn() }) }));
vi.mock('@/lib/i18n', () => ({ useLanguage: () => ({ language: 'en', t: (x: string) => x }) }));
vi.mock('@/lib/analytics', () => ({ trackEvent: () => undefined }));
vi.mock('@/lib/skill-template-map', () => ({ getSkillForTemplate: () => null }));
vi.mock('@/components/Settings', () => ({ useSettings: () => ({ settings: { providers: {}, preferences: { defaultExportMode: 'governance' } }, isLoaded: true }) }));
vi.mock('@/lib/hooks/useExecute', () => {
    const providers: never[] = [];
    const fetchProviders = () => undefined;
    return { useProviders: () => ({ providers, fetchProviders, anyConfigured: false }) };
});
vi.mock('@/components', async () => {
    const { DynamicForm } = await vi.importActual<typeof import('@/components/DynamicForm')>('@/components/DynamicForm');
    return { DynamicForm, ProcessingScreen: () => null,
        ResultViewer: ({ onRetry }: { onRetry: () => void }) => <button onClick={onRetry}>LocalRecover</button>,
        TemplatePreviewModal: () => null, OnboardingTour: () => null,
        AppBuilderWizard: () => null, ProductDesignWizard: () => null, MarketingCampaignWizard: () => null,
        BusinessStrategyWizard: () => null, SecurityAssessmentWizard: () => null, ResearchProjectWizard: () => null,
        SystemDesignWizard: () => null, ContentStrategyWizard: () => null, DataAnalysisWizard: () => null };
});
vi.mock('@/components/home/HomeBrowseExperience', () => ({ HomeBrowseExperience: () => null }));
let blobs: Blob[];
let prompts: string[];
let fetchSpy: ReturnType<typeof vi.spyOn>;
let baseline: string;
const capture = (e: Event) => prompts.push((e as CustomEvent<{ prompt: string }>).detail.prompt);
const click = (name: string) => fireEvent.click(screen.getByRole('button', { name }));
const change = (value: string, name = 'subject') => fireEvent.change(document.querySelector(`[name="${name}"]`)!, { target: { value } });
const status = () => screen.getByRole('status', { name: 'Trạng thái ý tưởng' });
const send = () => screen.getByRole('button', { name: 'Gửi Working Brief cho Agent INTAKE' }) as HTMLButtonElement;
const exportNow = () => fireEvent.click(screen.getByRole('button', { name: /^(Xác nhận ý tưởng và xuất cho agent|Xuất Working Brief cho agent \(\.md\))$/ }));
const text = (blob: Blob) => new Promise<string>((resolve) => {
    const r = new FileReader(); r.onload = () => resolve(String(r.result)); r.readAsText(blob);
});
beforeEach(async () => {
    localStorage.clear(); sessionStorage.clear(); blobs = []; prompts = [];
    const saved = (id: string, subject: string): Execution => ({ id, templateId: 'documentation', templateName: 'Local fixture',
        status: 'completed', createdAt: new Date('2026-10-01T00:00:00Z'), output: `${id}-OUTPUT`, intent: `${id}-INTENT`,
        input: { subject, currentNotes: `${id}-NOTES`, readerGoal: `${id}-GOAL`, audience: 'Quản lý / approver', mustPreserve: `${id}-KEEP` } });
    const a = saved('LOCAL-A', 'LOCAL-A-SOURCE'); const b = saved('LOCAL-B', 'LOCAL-B-SOURCE');
    useExecutionStore.setState({ executions: [b, a], currentExecution: b });
    baseline = localStorage.getItem('cvf-executions-storage')!;
    nav.p = new URLSearchParams('result=LOCAL-A');
    Object.defineProperty(URL, 'createObjectURL', { configurable: true, value: vi.fn((b: Blob) => { blobs.push(b); return 'blob:local'; }) });
    Object.defineProperty(URL, 'revokeObjectURL', { configurable: true, value: vi.fn() });
    Object.defineProperty(navigator, 'clipboard', { configurable: true, value: { writeText: vi.fn().mockResolvedValue(undefined) } });
    vi.spyOn(HTMLAnchorElement.prototype, 'click').mockImplementation(() => undefined);
    fetchSpy = vi.spyOn(globalThis, 'fetch').mockRejectedValue(new Error('LOCAL_NO_NETWORK'));
    window.addEventListener('cvf:openAgent', capture);
    render(<Home />); click('LocalRecover');
    fireEvent.click(screen.getByRole('button', { name: /Create Agent Spec/ }));
});
afterEach(() => { window.removeEventListener('cvf:openAgent', capture); expect(fetchSpy).not.toHaveBeenCalled(); vi.restoreAllMocks(); });
it('Local: view switches retain confirmation; source audience edit invalidates it', async () => {
    exportNow();
    expect(status().textContent).toContain('Đã xác nhận ý tưởng');
    click('Xem English Working Brief (tùy chọn)'); click('Ẩn English Working Brief');
    expect(send().disabled).toBe(false);
    change('Người mới tiếp nhận', 'audience');
    expect(status().textContent).toContain('Phiên bản ý tưởng 2');
    expect(status().textContent).toContain('Chưa xác nhận ý tưởng');
    expect(send().disabled).toBe(true); fireEvent.click(send()); expect(prompts).toEqual([]);
    exportNow();
    const revised = await text(blobs[1]); expect(revised).toContain('Người mới tiếp nhận');
    expect(revised).not.toContain('LOCAL-B'); click('Gửi Working Brief cho Agent INTAKE');
    expect(prompts).toEqual([revised]); expect(localStorage.getItem('cvf-executions-storage')).toBe(baseline);
});
it('Local: return to the same idea cannot revive old artifact and selected source excludes ambient B', async () => {
    exportNow(); const old = await text(blobs[0]);
    expect(old).toContain('LOCAL-A-SOURCE'); expect(old).not.toContain('LOCAL-B');
    await act(async () => { change('LOCAL-INTERIM'); });
    await act(async () => { change('LOCAL-A-SOURCE'); });
    expect(status().textContent).toContain('Phiên bản ý tưởng 3'); expect(send().disabled).toBe(true);
    click('Xem English Working Brief (tùy chọn)');
    expect(screen.getByRole('region', { name: 'English Working Brief' }).querySelector('pre')).toBeNull();
    exportNow(); const current = await text(blobs[1]);
    expect(current).toContain('Idea revision: 3'); expect(current).not.toContain('LOCAL-INTERIM'); expect(current).not.toContain('LOCAL-B');
    expect(screen.getByRole('region', { name: 'English Working Brief' }).querySelector('pre')!.textContent).toBe(current);
    click('Sao chép Working Brief'); await waitFor(() => expect(navigator.clipboard.writeText).toHaveBeenCalledWith(current));
    click('Gửi Working Brief cho Agent INTAKE'); expect(prompts).toEqual([current]);
    expect(localStorage.getItem('cvf-executions-storage')).toBe(baseline);
});
